// Lee lo que envió Vercel ({ "mensaje": "..." }) y lo deja listo para el agente.
// Vercel ya validó el mensaje, pero esta URL es pública: el workflow también se defiende.
const MIN = 3, MAX = 1000;
const mensaje = $input.first().json.body?.mensaje;
if (typeof mensaje !== 'string' || mensaje.trim().length < MIN || mensaje.length > MAX) {
  return [{ json: { valido: false } }];
}
return [{ json: { valido: true, mensaje: mensaje.trim() } }];

// El cuerpo no trae un «mensaje» de texto entre 3 y 1000 caracteres.
return [{ json: {
  http: 400,
  cuerpo: { ok: false, error: { codigo: 'validacion', mensaje: 'Escribe un mensaje de entre 3 y 1000 caracteres.',
                                detalle: 'falta el campo mensaje o su largo no es válido', reintentable: false } },
} }];

// EDITA AQUÍ · Corpus de políticas (sintético). Para tu caso, reemplaza la lista por tus documentos.
const POLITICAS = [{"id": "POL-01", "titulo": "Devoluciones", "texto": "Puedes devolver un producto dentro de 30 días corridos desde la fecha de entrega, siempre que esté sin uso, con sus etiquetas y con su boleta o número de pedido. No se aceptan devoluciones de productos personalizados, ropa interior ni alimentos. La devolución se solicita en la mesa de ayuda indicando el número de pedido. El envío de vuelta es gratuito si el producto llegó con falla o equivocado; en los demás casos lo paga el cliente."}, {"id": "POL-02", "titulo": "Cambios de talla o color", "texto": "Los cambios de talla o color se aceptan dentro de 15 días corridos desde la entrega, sujetos a stock. El producto debe estar sin uso y con etiquetas. Si no hay stock del producto solicitado, se ofrece una devolución según la política de devoluciones. Cada pedido admite un solo cambio."}, {"id": "POL-03", "titulo": "Despachos", "texto": "Tienda Nimbo despacha solo dentro de Chile. Plazos de entrega: Región Metropolitana, 2 a 4 días hábiles; otras regiones, 4 a 8 días hábiles; zonas extremas (Arica y Parinacota, Aysén y Magallanes), hasta 12 días hábiles. El despacho es gratuito en compras sobre $40.000; bajo ese monto cuesta $3.990. Un pedido se considera atrasado si supera el plazo máximo de su zona."}, {"id": "POL-04", "titulo": "Productos dañados o incorrectos", "texto": "Si un producto llega dañado o no corresponde a lo comprado, debes reportarlo dentro de 48 horas desde la entrega, adjuntando fotos del producto y del embalaje. Si el reporte llega a tiempo, Tienda Nimbo repone el producto sin costo o reembolsa el total, a elección del cliente. Los reportes fuera de plazo se evalúan como garantía."}, {"id": "POL-05", "titulo": "Garantía", "texto": "Todos los productos tienen 6 meses de garantía por fallas de fabricación, contados desde la entrega. La garantía no cubre daños por mal uso, golpes ni desgaste normal. Para usarla se requiere el número de pedido y una descripción de la falla; el producto pasa por una revisión técnica de hasta 10 días hábiles."}, {"id": "POL-06", "titulo": "Reembolsos", "texto": "Los reembolsos se hacen al mismo medio de pago de la compra, entre 5 y 10 días hábiles después de que el producto devuelto llega a bodega y es aprobado. Tienda Nimbo no hace reembolsos en efectivo ni a cuentas de terceros. El cliente recibe un correo cuando el reembolso es emitido."}];

// Búsqueda léxica BM25: sin embeddings ni servicios externos. Es el mismo algoritmo de busqueda.py (LangChain).
const PARADA = new Set(["a", "al", "cliente", "como", "con", "cual", "cuales", "cuando", "cuanto", "cuantos", "de", "del", "donde", "el", "en", "es", "esa", "ese", "esta", "este", "esto", "haber", "hace", "hacer", "hay", "la", "las", "le", "les", "lo", "los", "mas", "me", "mi", "nimbo", "no", "o", "para", "pedido", "pedidos", "por", "producto", "productos", "puede", "pueden", "puedo", "que", "quiero", "se", "ser", "si", "sin", "son", "su", "sus", "te", "tienda", "tiene", "tienen", "tu", "un", "una", "unas", "unos", "y", "ya"]);
const SINONIMOS = {"roto": ["danado"], "rota": ["danado"], "rotos": ["danado"], "rotas": ["danado"], "quebrado": ["danado"], "quebrada": ["danado"], "estropeado": ["danado"], "defectuoso": ["falla"], "tarda": ["plazo", "dias"], "demora": ["plazo", "dias"], "demoran": ["plazo", "dias"], "llega": ["despacho"], "llegar": ["despacho"], "envio": ["despacho"], "enviar": ["despacho"], "plata": ["reembolso"], "dinero": ["reembolso"], "reintegro": ["reembolso"], "arreglar": ["garantia"], "reparar": ["garantia"], "reparacion": ["garantia"], "devuelvo": ["devolver"], "devuelven": ["devolver"], "devolvieron": ["devolver"], "cambiar": ["cambio"], "talla": ["cambio"], "color": ["cambio"], "equivocado": ["incorrecto"], "equivocada": ["incorrecto"], "distinto": ["incorrecto"], "erroneo": ["incorrecto"], "atrasada": ["atrasado"], "atraso": ["atrasado"], "retraso": ["atrasado"], "retrasado": ["atrasado"]};
const K1 = 1.5, B = 0.75, LARGO_RAIZ = 5, K = 3;

const normalizar = (t) => String(t).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const palabras = (t) => (normalizar(t).match(/[a-z0-9]+/g) || []).filter(p => !PARADA.has(p) && p.length > 1);
const raices = (lista) => lista.map(p => p.slice(0, LARGO_RAIZ));

const docs = POLITICAS.map(p => ({ p, terminos: raices(palabras(`${p.id} ${p.titulo} ${p.titulo} ${p.texto}`)) }));
const largoMedio = docs.reduce((s, d) => s + d.terminos.length, 0) / docs.length;
const frecuenciaDoc = {};
docs.forEach(d => new Set(d.terminos).forEach(t => { frecuenciaDoc[t] = (frecuenciaDoc[t] || 0) + 1; }));

const base = palabras(query);
const consulta = raices(base.concat(...base.map(p => SINONIMOS[p] || [])));

const resultados = docs.map(d => {
  let total = 0;
  new Set(consulta).forEach(t => {
    const f = d.terminos.filter(x => x === t).length;
    if (!f) return;
    const df = frecuenciaDoc[t];
    const idf = Math.log(1 + (docs.length - df + 0.5) / (df + 0.5));
    total += idf * f * (K1 + 1) / (f + K1 * (1 - B + B * d.terminos.length / largoMedio));
  });
  return { p: d.p, puntaje: Math.round(total * 1e9) / 1e9 };
}).filter(r => r.puntaje > 0)
  .sort((a, b) => (b.puntaje - a.puntaje) || (a.p.id < b.p.id ? -1 : 1))
  .slice(0, K);

if (!resultados.length) return 'Ninguna política coincide con la consulta.';
return resultados.map(r => `${r.p.id} · ${r.p.titulo}\n${r.p.texto}`).join('\n\n');

// EDITA AQUÍ · Lógica de la tool consultar_pedido (tabla sintética de pedidos).
// En un caso real, aquí iría una consulta a tu base de datos o a la API de tu tienda.
const FECHA_REFERENCIA = '2026-10-15'; // "hoy" fijo, para resultados reproducibles
const PEDIDOS = [{"n_pedido": 1001, "fecha_compra": "2026-09-01", "fecha_entrega": "2026-09-04", "estado": "entregado", "producto": "Polerón algodón orgánico", "categoria": "vestuario", "region": "Metropolitana", "monto_clp": 24990}, {"n_pedido": 1002, "fecha_compra": "2026-09-03", "fecha_entrega": "2026-09-10", "estado": "entregado", "producto": "Mochila urbana 25L", "categoria": "accesorios", "region": "Valparaíso", "monto_clp": 39990}, {"n_pedido": 1003, "fecha_compra": "2026-10-08", "fecha_entrega": null, "estado": "en_transito", "producto": "Chaqueta impermeable", "categoria": "vestuario", "region": "Los Lagos", "monto_clp": 69990}, {"n_pedido": 1004, "fecha_compra": "2026-09-10", "fecha_entrega": "2026-09-13", "estado": "entregado", "producto": "Botella térmica 1L", "categoria": "hogar", "region": "Metropolitana", "monto_clp": 14990}, {"n_pedido": 1005, "fecha_compra": "2026-09-12", "fecha_entrega": null, "estado": "cancelado", "producto": "Lámpara de escritorio LED", "categoria": "hogar", "region": "Biobío", "monto_clp": 29990}, {"n_pedido": 1006, "fecha_compra": "2026-09-15", "fecha_entrega": "2026-09-22", "estado": "entregado", "producto": "Set de sartenes antiadherentes", "categoria": "hogar", "region": "Araucanía", "monto_clp": 59990}, {"n_pedido": 1007, "fecha_compra": "2026-10-01", "fecha_entrega": "2026-10-05", "estado": "entregado", "producto": "Zapatillas trail Nimbo Pro", "categoria": "calzado", "region": "Metropolitana", "monto_clp": 54990}, {"n_pedido": 1008, "fecha_compra": "2026-09-18", "fecha_entrega": "2026-09-24", "estado": "entregado", "producto": "Polera personalizada con nombre", "categoria": "vestuario", "region": "Maule", "monto_clp": 19990}, {"n_pedido": 1009, "fecha_compra": "2026-10-10", "fecha_entrega": null, "estado": "en_preparacion", "producto": "Audífonos inalámbricos", "categoria": "tecnologia", "region": "Metropolitana", "monto_clp": 44990}, {"n_pedido": 1010, "fecha_compra": "2026-09-20", "fecha_entrega": null, "estado": "cancelado", "producto": "Silla ergonómica", "categoria": "hogar", "region": "Coquimbo", "monto_clp": 149990}, {"n_pedido": 1011, "fecha_compra": "2026-09-22", "fecha_entrega": "2026-09-30", "estado": "entregado", "producto": "Parka de plumas", "categoria": "vestuario", "region": "Magallanes", "monto_clp": 89990}, {"n_pedido": 1012, "fecha_compra": "2026-09-24", "fecha_entrega": "2026-09-28", "estado": "entregado", "producto": "Cafetera de émbolo 1L", "categoria": "hogar", "region": "Metropolitana", "monto_clp": 22990}, {"n_pedido": 1013, "fecha_compra": "2026-10-02", "fecha_entrega": "2026-10-09", "estado": "entregado", "producto": "Jeans corte recto", "categoria": "vestuario", "region": "Antofagasta", "monto_clp": 34990}, {"n_pedido": 1014, "fecha_compra": "2026-10-05", "fecha_entrega": null, "estado": "en_transito", "producto": "Teclado mecánico", "categoria": "tecnologia", "region": "Aysén", "monto_clp": 64990}, {"n_pedido": 1015, "fecha_compra": "2026-08-15", "fecha_entrega": "2026-08-20", "estado": "entregado", "producto": "Hervidor eléctrico", "categoria": "hogar", "region": "Metropolitana", "monto_clp": 27990}, {"n_pedido": 1016, "fecha_compra": "2026-10-06", "fecha_entrega": "2026-10-09", "estado": "entregado", "producto": "Calcetines de lana pack 3", "categoria": "vestuario", "region": "Metropolitana", "monto_clp": 12990}, {"n_pedido": 1017, "fecha_compra": "2026-09-28", "fecha_entrega": "2026-10-07", "estado": "entregado", "producto": "Carpa 2 personas", "categoria": "deportes", "region": "Ñuble", "monto_clp": 99990}, {"n_pedido": 1018, "fecha_compra": "2026-10-12", "fecha_entrega": null, "estado": "en_preparacion", "producto": "Smartwatch deportivo", "categoria": "tecnologia", "region": "Valparaíso", "monto_clp": 119990}, {"n_pedido": 1019, "fecha_compra": "2026-07-30", "fecha_entrega": "2026-08-05", "estado": "entregado", "producto": "Bicicleta urbana aro 28", "categoria": "deportes", "region": "Metropolitana", "monto_clp": 329990}, {"n_pedido": 1020, "fecha_compra": "2026-10-09", "fecha_entrega": null, "estado": "en_transito", "producto": "Termo para mate", "categoria": "hogar", "region": "Araucanía", "monto_clp": 17990}];

const dias = (desde, hasta) => Math.round((Date.parse(hasta) - Date.parse(desde)) / 86400000);
const n = Number(query.n_pedido);
const pedido = PEDIDOS.find(p => p.n_pedido === n);
if (!pedido) {
  return JSON.stringify({ encontrado: false, n_pedido: n, mensaje: 'No existe un pedido con ese número.' });
}
const respuesta = { encontrado: true, ...pedido, dias_desde_compra: dias(pedido.fecha_compra, FECHA_REFERENCIA) };
if (pedido.fecha_entrega) respuesta.dias_desde_entrega = dias(pedido.fecha_entrega, FECHA_REFERENCIA);
return JSON.stringify(respuesta);

// EDITA AQUÍ · Convierte lo que devolvió el agente en la respuesta que espera la pantalla (contrato v1).
// Solo hace falta entregar: respuesta, pedido y pasos. Vercel agrega estado, citas y meta, y descarta lo que sobre.
const MODELO = 'nvidia/nemotron-3-ultra-550b-a55b:free';   // informativo: debe coincidir con el nodo «Modelo · Nemotron»

const salida = $input.first().json;
const texto = String(salida.output ?? '').trim();
const pasosCrudos = Array.isArray(salida.intermediateSteps) ? salida.intermediateSteps : [];

if (!texto || /agent stopped due to max iterations/i.test(texto)) {
  return [{ json: {
    http: 502,
    cuerpo: { ok: false, error: { codigo: 'backend', mensaje: 'El agente no logró terminar su respuesta.',
                                  detalle: texto || 'el agente no devolvió texto', reintentable: true } },
  } }];
}

const comoTexto = (v) => (typeof v === 'string' ? v : JSON.stringify(v ?? ''));
const comoJson = (s) => { try { return JSON.parse(s); } catch { return null; } };

// n8n entrega el resultado de cada tool como un texto con esta forma: [{"response":"..."}]. Aquí se saca el texto interno.
const desenvolver = (obs) => {
  const externo = comoJson(comoTexto(obs));
  if (Array.isArray(externo) && externo.length && externo.every(x => x && typeof x === 'object' && 'response' in x)) {
    return externo.map(x => comoTexto(x.response)).join('\n');
  }
  return comoTexto(obs);
};

let pedido = null;
const pasos = pasosCrudos.map((paso) => {
  const herramienta = paso.action?.tool ?? 'herramienta';
  const entrada = paso.action?.toolInput ?? {};
  const observacion = desenvolver(paso.observation);
  let detalle = '';
  if (herramienta === 'consultar_pedido') {
    const datos = comoJson(observacion);
    const n = entrada.n_pedido ?? datos?.n_pedido ?? '?';
    if (datos?.encontrado) {
      // a la pantalla solo viaja lo que el contrato necesita
      pedido = { n_pedido: datos.n_pedido, estado: datos.estado, producto: datos.producto,
                 fecha_entrega: datos.fecha_entrega ?? null, dias_desde_entrega: datos.dias_desde_entrega ?? null };
      detalle = `n_pedido = ${n} → ` + (datos.dias_desde_entrega != null ? `${datos.estado} hace ${datos.dias_desde_entrega} días` : datos.estado);
    } else {
      detalle = `n_pedido = ${n} → no existe`;
    }
  } else if (herramienta === 'buscar_politicas') {
    const codigos = [...new Set(observacion.match(/POL-\d\d/g) ?? [])];
    detalle = `«${entrada.input ?? entrada.query ?? ''}» → ${codigos.join(', ') || 'sin coincidencias'}`;
  } else {
    detalle = observacion.slice(0, 120);
  }
  return { tipo: 'herramienta', nombre: herramienta, detalle };
});

return [{ json: {
  http: 200,
  cuerpo: { respuesta: texto, pedido, pasos, modelo: MODELO, llamadas_modelo: null },
} }];

// El agente falló (modelo sin cuota, clave rechazada, tiempo agotado...). En vez de dejar que n8n responda con un
// error genérico, se traduce a la forma del contrato v1 para que la pantalla explique qué pasó.
const bruto = $input.first().json;
const original = String(bruto.error?.message ?? bruto.error ?? bruto.message ?? 'error desconocido');
const detalle = original.replace(/sk-[A-Za-z0-9_-]+/g, '[clave]').replace(/\s+/g, ' ').slice(0, 160);  // nunca reenvíes claves

let codigo = 'backend', mensaje = 'El agente falló al llamar al modelo.', reintentable = false;
if (/429|rate.?limit|quota|free-models|too many requests/i.test(original)) {
  codigo = 'cuota_ia'; mensaje = 'El modelo gratuito alcanzó su límite de uso.'; reintentable = true;
} else if (/timed? ?out|timeout|took too long|ETIMEDOUT|ECONNRESET|ECONNABORTED/i.test(original)) {
  codigo = 'timeout'; mensaje = 'El modelo tardó demasiado en responder.'; reintentable = true;
} else if (/max(imum)? iterations/i.test(original)) {
  mensaje = 'El agente no logró terminar su respuesta con las herramientas disponibles.'; reintentable = true;
} else if (/401|403|unauthorized|forbidden|no auth|invalid api key|authentication|authorization failed|check your credentials/i.test(original)) {
  mensaje = 'n8n no pudo autenticarse con OpenRouter: revisa la credencial del modelo.';
} else if (/5\d\d|provider returned error|overloaded|unavailable|bad gateway|failed to handle|not able to process/i.test(original)) {
  mensaje = 'El proveedor del modelo no está disponible en este momento.'; reintentable = true;
}
return [{ json: { http: 502, cuerpo: { ok: false, error: { codigo, mensaje, detalle, reintentable } } } }];
